def count_range_sum(nums: list[int], lower: int, upper: int) -> int:
    prefix = [0]
    for value in nums:
        prefix.append(prefix[-1] + value)

    def sort_count(lo: int, hi: int) -> int:
        # sorts prefix[lo:hi] and returns the number of valid pairs inside it
        if hi - lo <= 1:
            return 0
        mid = (lo + hi) // 2
        count = sort_count(lo, mid) + sort_count(mid, hi)
        left = prefix[lo:mid]
        start = end = 0  # window [start, end) of left values in range
        for k in range(mid, hi):
            p = prefix[k]
            while start < len(left) and left[start] < p - upper:
                start += 1
            while end < len(left) and left[end] <= p - lower:
                end += 1
            count += end - start
        prefix[lo:hi] = sorted(prefix[lo:hi])  # merge of two sorted runs
        return count

    return sort_count(0, len(prefix))

def min_stickers(stickers: list[str], target: str) -> int:
    needed = set(target)
    # letter counts per sticker, restricted to letters the target uses
    kits = []
    for word in stickers:
        counts = Counter(ch for ch in word if ch in needed)
        if counts:
            kits.append(counts)

    INF = float("inf")

    @lru_cache(maxsize=None)
    def solve(remaining: str) -> float:
        if not remaining:
            return 0
        first = remaining[0]
        best = INF
        for kit in kits:
            if first not in kit:
                continue  # some sticker must cover `first`; try those now
            avail = dict(kit)
            left = []
            for ch in remaining:
                if avail.get(ch, 0) > 0:
                    avail[ch] -= 1
                else:
                    left.append(ch)
            best = min(best, 1 + solve("".join(left)))
        return best

    answer = solve("".join(sorted(target)))
    return -1 if answer == INF else answer

