def tallest_billboard(rods: list[int]) -> int:
    remaining = sum(rods)
    best = {0: 0}  # difference between supports -> tallest shorter support
    for r in rods:
        remaining -= r
        nxt = dict(best)  # option: leave the rod unused
        for diff, low in best.items():
            # put the rod on the taller support
            d = diff + r
            if d <= remaining and nxt.get(d, -1) < low:
                nxt[d] = low
            # put the rod on the shorter support
            d = abs(diff - r)
            h = low + min(diff, r)
            if d <= remaining and nxt.get(d, -1) < h:
                nxt[d] = h
        # drop differences that the leftover rods can never close
        best = {d: h for d, h in nxt.items() if d <= remaining}
    return best.get(0, 0)

