def has_valid_path(grid: list[list[int]]) -> bool:
    m, n = len(grid), len(grid[0])
    up, down, left, right = (-1, 0), (1, 0), (0, -1), (0, 1)
    openings = {1: (left, right), 2: (up, down), 3: (left, down),
                4: (right, down), 5: (left, up), 6: (right, up)}
    seen = [[False] * n for _ in range(m)]
    seen[0][0] = True
    queue = deque([(0, 0)])
    while queue:
        r, c = queue.popleft()
        if r == m - 1 and c == n - 1:
            return True
        for dr, dc in openings[grid[r][c]]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and not seen[nr][nc]:
                # the neighbour must open back toward us
                if (-dr, -dc) in openings[grid[nr][nc]]:
                    seen[nr][nc] = True
                    queue.append((nr, nc))
    return False

