    def snake(m, n, broken):
        up, down, left, right = (-1, 0), (1, 0), (0, -1), (0, 1)
        piece = {frozenset((left, right)): 1, frozenset((up, down)): 2, frozenset((left, down)): 3,
                 frozenset((right, down)): 4, frozenset((left, up)): 5, frozenset((right, up)): 6}
        path = []
        for r in range(m):
            cols = range(n) if r % 2 == 0 else range(n - 1, -1, -1)
            path.extend((r, c) for c in cols)
        grid = [[random.randint(1, 6) for _ in range(n)] for _ in range(m)]
        for i, (r, c) in enumerate(path):
            dirs = set()
            if i > 0:
                pr, pc = path[i - 1]; dirs.add((pr - r, pc - c))
            if i + 1 < len(path):
                nr, nc = path[i + 1]; dirs.add((nr - r, nc - c))
            if len(dirs) == 1:
                d = next(iter(dirs))
                dirs.add(left if d != left else up)
            grid[r][c] = piece[frozenset(dirs)]
        if broken:
            r, c = path[-2]
            grid[r][c] = 2 if grid[r][c] == 1 else 1
        return grid
    return [[snake(101, 101, False)], [snake(101, 101, True)]]

